/**
 * A feed date after parsing: the instant, its civil parts in UTC, and the two
 * serializations the feed formats ask for.
 */
export interface JsParsedFeedDate {
  /** Seconds since the Unix epoch. */
  unix: number
  /** Civil year in UTC. */
  year: number
  /** Civil month, 1-12. */
  month: number
  /** Civil day of month, 1-31. */
  day: number
  /** Hour, 0-23. */
  hour: number
  /** Minute, 0-59. */
  minute: number
  /** Second, 0-60. */
  second: number
  /** `YYYY-MM-DDTHH:MM:SSZ`, as Atom and JSON Feed want it. */
  rfc3339: string
  /** `Day, DD Mon YYYY HH:MM:SS +0000`, as RSS wants it. */
  rfc822: string
}

/**
 * Parser options for JavaScript.
 *
 * When `gfm` is `true`, omitted extension flags inherit the GFM profile.
 */
export interface JsParserOptions {
  /**
   * Enable the GFM convenience profile.
   *
   * Default: `false`.
   */
  gfm?: boolean
  /**
   * Enable MDX JSX, ESM, and expression nodes.
   *
   * Default: `false`.
   */
  mdx?: boolean
  /**
   * Enable footnote references and definitions.
   *
   * Default: `false`, or `true` when `gfm` is `true`.
   */
  footnotes?: boolean
  /**
   * Enable GFM task-list item markers.
   *
   * Default: `false`, or `true` when `gfm` is `true`.
   */
  taskLists?: boolean
  /**
   * Enable GFM pipe tables.
   *
   * Default: `false`, or `true` when `gfm` is `true`.
   */
  tables?: boolean
  /**
   * Enable GFM strikethrough spans.
   *
   * Default: `false`, or `true` when `gfm` is `true`.
   */
  strikethrough?: boolean
  /**
   * Enable GFM autolinks.
   *
   * Default: `false`, or `true` when `gfm` is `true`.
   */
  autolinks?: boolean
}

/** Opt-in parameterized Markdown partials. */
export interface JsPartialsOptions {
  /**
   * Enable `<!-- @partial: PATH k="v" -->` expansion.
   *
   * Default: `false`.
   */
  enabled?: boolean
  /**
   * Root directory used for `@/` and absolute partial paths.
   *
   * Default: project root from the JavaScript caller.
   */
  rootDir?: string
  /**
   * Directory used for bare partial names such as `install.md`.
   *
   * Default: `"_partials"`.
   */
  root?: string
  /**
   * Missing `{{ name }}` substitutions: `"literal"` (default) or `"error"`.
   *
   * Default: `"literal"`.
   */
  missing?: string
}

/** A block the native pass left for the caller's highlighter. */
export interface JsPendingBlock {
  /** The `language-…` class the block carries. */
  language: string
  /** The block's source text, already unescaped. */
  source: string
}

/** Options for [`super::transform_pm_embeds`]. */
export interface JsPmOptions {
  /**
   * Enable opt-in synced package-manager tab groups. When `true`, a
   * `data-ox-tab-group="pkg-manager"` attribute is emitted so the client
   * runtime keeps every pm tab group on the page in sync via `localStorage`.
   * Off by default; when omitted/`false` the output has no group attribute
   * and behaves exactly like a standalone tab group.
   */
  sync?: boolean
}

/** Result of [`super::transform_pm_embeds`]. */
export interface JsPmTransformResult {
  /** HTML with every `<pm>` block expanded into a package-manager tab widget. */
  html: string
  /**
   * Number of tab groups expanded; the caller advances its shared tab-group
   * counter by this amount.
   */
  groupCount: number
}

